head.script:
scwin.onpageload = async function () {

    // window.App 객체가 로드될 때까지 잠시 기다리는 안전장치 추가

    await scwin.checkAppReady();
    console.log("Application classes are loaded. Application starting...");
    const { UIManager, RoomClient, loadModule } = window.App;

    scwin.uiManager = new UIManager();
    const roomClient = new RoomClient(scwin.uiManager);

    let aiModule = null;
    let canvasModule = null;
    let wsInstance = null;

    scwin.pinnedProducerId = null;
    scwin.remoteElements = new Map(); // 원격 미디어 요소를 관리하는 Map
    scwin.remoteCanvasModules = new Map(); // 원격 화면 공유용 캔버스 모듈을 관리하는 Map

    let isAudioEnabled = true;
    let isVideoEnabled = true;
    let isScreenSharing = false;
    let isWhiteboardActive = false;

    const CANVAS_WEBSOCKET_URL = 'wss://' + location.host + '/InsWebApp/signal.do';
    const CANVAS_WORKER_URL = '/InsWebApp/js/canvas/canvas-worker.js'
    const MEDIA_PIPE_WORKER_URL = '/InsWebApp/media/dist/mediapipe.worker.bundle.js'

    // --- 모듈 보유 여부 (원래는 서버에서 받아와야 할 값) ---

    const userHasAiModule = true;
    const userHasCanvasModule = true;
    const userHasScreenShareModule = true;

    // WebSocket 연결이 성공하면, 보유한 모듈 관련 UI를 설정합니다.
    roomClient.on("connected", (ws) => {
        wsInstance = ws; // WebSocket 인스턴스 저장
        if (userHasCanvasModule) {
            scwin.uiManager.showWhiteboardButton();
        }
    });

    // 관리자 여부와 모듈 보유 여부를 모두 확인하여 화면 공유 기능 활성화
    roomClient.on("adminStatus", (isAdmin) => {
        if (userHasScreenShareModule && isAdmin) {
            scwin.uiManager.enableScreenSharing(() => {
                if (isScreenSharing) {
                    roomClient.stopScreenShare();
                } else {
                    // 칠판 모드가 활성화되어 있으면 비활성화 후 화면 공유 시작
                    if (isWhiteboardActive) {
                        scwin.uiManager.whiteboardButton.click();
                    }
                    roomClient.startScreenShare();
                }
            });
        }
    });

    // 칠판 버튼 클릭 이벤트 핸들러
    scwin.uiManager.whiteboardButton.onclick = async () => {
        if (!wsInstance) {
            console.error("WebSocket is not connected. Cannot toggle whiteboard.");
            return;
        }
        isWhiteboardActive = !isWhiteboardActive;

        if (isWhiteboardActive) {
            // 화면 공유 중이라면 중지
            if (isScreenSharing) await roomClient.stopScreenShare();

            try {
                let CanvasModule = await loadModule(
                    "/InsWebApp/media/dist/modules/canvas.bundle.js",
                    "CanvasModule"
                );
                if (CanvasModule && !CanvasModule.prototype) {
                    CanvasModule = CanvasModule.CanvasModule || CanvasModule.default;
                }
                const container = scwin.uiManager.getMainStageContainer();

                const canvasContainer = document.createElement("div");
                canvasContainer.id = "canvasStandaloneContainer";
                canvasContainer.style.cssText = `position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: #FFFFFF;`;

                container.appendChild(canvasContainer);

                //canvasModule = new CanvasModule(canvasContainer, wsInstance);
                canvasModule = new CanvasModule(canvasContainer, CANVAS_WEBSOCKET_URL, CANVAS_WORKER_URL);
                canvasModule.on("ready", () => {
                    canvasModule.signal({ type: "bg-change", color: "#FFFFFF" });
                });
                scwin.uiManager.whiteboardButton.textContent = "칠판 끄기";
            } catch (error) {
                console.error("Failed to load CanvasModule:", error);
            }
        } else {
            if (canvasModule) {
                canvasModule.destroy();
                canvasModule = null;
            }
            const container = document.getElementById("canvasStandaloneContainer");
            if (container) container.remove();
            scwin.uiManager.whiteboardButton.textContent = "칠판";
        }
    };

    // 화면 공유 상태가 변경되면 UI 업데이트
    roomClient.on("screenShareState", ({ isSharing }) => {
        isScreenSharing = isSharing;
        scwin.uiManager.screenShareButton.textContent = isSharing
            ? "공유 중지"
            : "화면 공유";
    });

    // RoomClient가 컨트롤 준비 완료를 방송하면, UIManager가 버튼을 활성화합니다.
    roomClient.on("controlsReady", () => {
        scwin.uiManager.enableControls();
        scwin.uiManager.cameraOffButton.onclick = () => {
            isVideoEnabled = !isVideoEnabled;
            roomClient.setVideoEnabled(isVideoEnabled);
            scwin.uiManager.cameraOffButton.textContent = isVideoEnabled
                ? "카메라 끄기"
                : "카메라 켜기";
            if (aiModule) {
                isVideoEnabled ? aiModule.start() : aiModule.stop();
            }
        };
        scwin.uiManager.muteButton.onclick = () => {
            isAudioEnabled = !isAudioEnabled;
            roomClient.setAudioEnabled(isAudioEnabled);
            scwin.uiManager.muteButton.textContent = isAudioEnabled
                ? "음소거"
                : "음소거 해제";
        };
    });

    // 원격 트랙 수신 처리
    roomClient.on("new-consumer", async (consumer) => {
        const { track, producerId, appData } = consumer;
        let elementWrapper;
        const key = (appData && appData.source === 'screen') ? `screen-${producerId}` : producerId;

        if (appData && appData.source === 'screen') {
            elementWrapper = document.createElement("div");
            elementWrapper.id = `remote-screen-${producerId}`;
            elementWrapper.classList.add("screen-share-wrapper");

            // 원격 화면 공유 위에 그림을 그릴 캔버스 오버레이 추가
            if (userHasCanvasModule) {
                try {
                    let CanvasModule = await loadModule("/InsWebApp/media/dist/modules/canvas.bundle.js", "CanvasModule");
                    if (CanvasModule && !CanvasModule.prototype) {
                        CanvasModule = CanvasModule.CanvasModule || CanvasModule.default;
                    }
                    const canvasContainer = document.createElement("div");
                    canvasContainer.id = `canvas-overlay-${producerId}`;
                    canvasContainer.style.cssText = `position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 10; pointer-events: none;`;
                    elementWrapper.appendChild(canvasContainer);

                    const remoteCanvasModule = new CanvasModule(canvasContainer, CANVAS_WEBSOCKET_URL, CANVAS_WORKER_URL);
                    scwin.remoteCanvasModules.set(producerId, remoteCanvasModule);
                } catch (error) {
                    console.error("Failed to create canvas overlay for remote screen share:", error);
                }
            }

        } else if (track.kind === 'video') {
            elementWrapper = document.createElement('div');
            elementWrapper.id = `remote-video-${producerId}`;
            elementWrapper.onclick = () => {
                if (Array.from(scwin.remoteElements.values()).some(el => el.classList.contains('screen-share-wrapper'))) {
                    alert("화면 공유 중에는 다른 화면을 고정할 수 없습니다.");
                    return;
                }
                scwin.pinnedProducerId = (scwin.pinnedProducerId === producerId) ? null : producerId;
                scwin.updateVideoLayout();
            };
        } else if (track.kind === 'audio') {
            const audioEl = document.createElement('audio');
            audioEl.id = `remote-audio-${producerId}`;
            audioEl.srcObject = new MediaStream([track]);
            audioEl.autoplay = true;
            document.body.appendChild(audioEl);
            return;
        }

        if (elementWrapper) {
            const mediaEl = document.createElement(track.kind);
            mediaEl.srcObject = new MediaStream([track]);
            mediaEl.autoplay = true;
            mediaEl.playsInline = true;
            elementWrapper.appendChild(mediaEl);
            scwin.remoteElements.set(key, elementWrapper);
            scwin.updateVideoLayout();
        }
    });



    // 원격 트랙 종료 처리
    roomClient.on("producer-closed", (producerId) => {
        const screenShareKey = `screen-${producerId}`;
        const videoKey = producerId;

        // 화면 공유 트랙이 닫혔는지 확인
        if (scwin.remoteElements.has(screenShareKey)) {
            // 캔버스 모듈 정리
            const remoteCanvasModule = scwin.remoteCanvasModules.get(producerId);
            if (remoteCanvasModule) {
                remoteCanvasModule.destroy();
                scwin.remoteCanvasModules.delete(producerId);
            }
            // DOM에서 화면 공유 래퍼 명시적으로 제거
            const screenShareWrapper = document.getElementById(`remote-screen-${producerId}`);
            if (screenShareWrapper) {
                screenShareWrapper.remove();
            }
            scwin.remoteElements.delete(screenShareKey);
        } else if (scwin.remoteElements.has(videoKey)) {
            // 비디오 트랙 정리
            const videoWrapper = document.getElementById(`remote-video-${producerId}`);
            if (videoWrapper) {
                videoWrapper.remove();
            }
            scwin.remoteElements.delete(videoKey);
        }

        // 오디오 트랙 정리
        const audioEl = document.getElementById(`remote-audio-${producerId}`);
        if (audioEl) {
            audioEl.remove();
        }

        if (scwin.pinnedProducerId === producerId) {
            scwin.pinnedProducerId = null;
        }
        scwin.updateVideoLayout(); // 레이아웃 업데이트
    });


    // 로컬 화면 공유 시작/중지 이벤트 처리

    roomClient.on("local-screen-share-started", async (track) => {
        const screenShareWrapper = document.createElement("div");
        screenShareWrapper.id = "local-screen-share-wrapper";
        screenShareWrapper.classList.add("screen-share-wrapper");

        const element = document.createElement(track.kind);
        element.srcObject = new MediaStream([track]);
        element.muted = true;
        element.autoplay = true;
        element.playsInline = true;
        screenShareWrapper.appendChild(element);

        scwin.remoteElements.set("local-screen-share", screenShareWrapper);
        scwin.updateVideoLayout();

        if (userHasCanvasModule) {
            try {
                let CanvasModule = await loadModule(
                    "/InsWebApp/media/dist/modules/canvas.bundle.js",
                    "CanvasModule"
                );
                if (CanvasModule && !CanvasModule.prototype) {
                    CanvasModule = CanvasModule.CanvasModule || CanvasModule.default;
                }
                const canvasContainer = document.createElement("div");
                canvasContainer.id = "canvasOverlayContainer";
                canvasContainer.style.cssText = `position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 10;`;

                screenShareWrapper.appendChild(canvasContainer);

                //canvasModule = new CanvasModule(canvasContainer, wsInstance);
                canvasModule = new CanvasModule(canvasContainer, CANVAS_WEBSOCKET_URL, CANVAS_WORKER_URL);
            } catch (error) {
                console.error("Failed to load CanvasModule for overlay:", error);
            }
        }
        scwin.updateVideoLayout();
    });
    roomClient.on("local-screen-share-stopped", () => {
        scwin.remoteElements.delete("local-screen-share");
        scwin.updateVideoLayout();
        if (canvasModule) {
            canvasModule.destroy();
            canvasModule = null;
        }
        // 로컬 화면 공유 종료 시 캔버스 오버레이 컨테이너 및 화면 공유 래퍼 제거
        const canvasOverlayContainer = document.getElementById("canvasOverlayContainer");
        if (canvasOverlayContainer) {
            canvasOverlayContainer.remove();
        }
        const localScreenShareWrapper = document.getElementById("local-screen-share-wrapper");
        if (localScreenShareWrapper) {
            localScreenShareWrapper.remove(); // DOM에서 직접 제거
        }
    });


    roomClient.on("remote-producer-pause", ({ producerId }) => {
        const videoWrapper = scwin.remoteElements.get(producerId); 
        if (videoWrapper) {
            videoWrapper.classList.add('video-paused');
        }
    }); roomClient.on("remote-producer-resume", ({ producerId }) => {
        const videoWrapper = scwin.remoteElements.get(producerId);
        if (videoWrapper) {
            videoWrapper.classList.remove('video-paused');
        }
    });


    // AI 모듈 초기화 로직
    if (userHasAiModule) {
        try {
            let MediaPipeModule = await loadModule(
                "/InsWebApp/media/dist/modules/mediapipe.bundle.js",
                "MediaPipeModule"
            );
            if (MediaPipeModule && !MediaPipeModule.prototype) {
                MediaPipeModule = MediaPipeModule.MediaPipeModule || MediaPipeModule.default;
            }
            const videoElement = document.getElementById("localVideo");
            aiModule = new MediaPipeModule(videoElement, MEDIA_PIPE_WORKER_URL);
            console.log("AI Module will be initialized.");

            roomClient.on("localStreamReady", () => {
                if (aiModule) aiModule.start();
            });
            aiModule.on("landmarksUpdate", (landmarks) => {
                scwin.uiManager.drawFaceMesh(landmarks);
            });


            // 3. AI 모듈이 '상태 변경'을 방송하면, RoomClient가 서버로 데이터를 전송합니다.
            // 졸음 감지
            aiModule.on("drowsinessDetected", (data) => {
                console.log("Event: drowsinessUpdate -> Sending status to server.");
                scwin.createPopUp(
                    "drowsinessPopUp",
                    "Warning !!",
                    null,
                    "/InsWebApp/ui/media_pipe_pop_up/drowsiness_pop_up.xml",
                    400,
                    425
                );
                roomClient.sendPeerStatus(data);
            });
            aiModule.on("drowsinessResolved", (data) => {
                console.log("Event: drowsinessUpdate -> Sending status to server.");
                roomClient.sendPeerStatus(data);
            });

            // 자리비움 감지
            aiModule.on("absenceStarted", (data) => {
                console.log(" Event: absenceStarted -> Sending status to server.");
                scwin.createPopUp(
                    "adfPopUp",
                    "Warning !!",
                    null,
                    "/InsWebApp/ui/media_pipe_pop_up/afd_pop_up.xml",
                    400,
                    475
                );
                roomClient.sendPeerStatus(data);
            });
            aiModule.on("absenceEnded", (data) => {
                console.log(" Event: absenceEnded -> Sending status to server.");
                roomClient.sendPeerStatus(data);
            });

            // 4. AI 모듈에서 에러가 발생하면 콘솔에 출력합니다.
            aiModule.on("error", (error) => {
                console.error(" AI Module Error:", error);
            });
        } catch (error) {
            console.error("Failed to load MediaPipeModule:", error);
        }
    }
    const roomId = "my-first-room";
    roomClient.join(roomId);
}

scwin.createPopUp = function (_id, _name, _jsnData, url, _popupWidth, _popupHeight) {
    if ($p.getPopup(_id)) {
        console.log(`Popup with ID '${_id}' already exists. Skipping creation.`);
        return; // 이미 팝업이 있으면 함수를 종료
    }
    // 팝업 크기를 변수로 지정 (계산에 사용하기 위함)
    var popupWidth = _popupWidth;
    var popupHeight = _popupHeight;

    var topPosition = (window.innerHeight - popupHeight) / 2;
    var leftPosition = (window.innerWidth - popupWidth) / 2;
    // 팝업 생성 옵션 지정
    var options = {
        id: _id,
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: topPosition + "px",
        left: leftPosition + "px",
        popupName: _name,
        modal: true,
        closeAction: "scwin.popup_closeAction", // [선택] 팝업의 닫기 버튼을 클릭했을 때 실행할 함수명
        dataObject: _jsnData
    };

    // 팝업 생성
    $p.openPopup(url, options);
}

scwin.checkAppReady = function () {
    return new Promise(resolve => {
        const interval = setInterval(() => {
            console.log(window.App)
            // 'window.App'과 그 안의 내용이 모두 준비되었는지 확인
            if (window.App && window.App.UIManager && window.App.RoomClient) {
                clearInterval(interval);
                resolve();
            }
        }, 50);
    });
};



/**
 * 비디오 컨테이너의 레이아웃을 동적으로 업데이트하는 함수
 */

scwin.updateVideoLayout = function () {
    const mainStage = scwin.uiManager.getMainStageContainer();
    const sidebar = scwin.uiManager.getSidebarContainer();

    const allElements = Array.from(scwin.remoteElements.values());
    const screenShareElement = allElements.find(el => el.classList.contains('screen-share-wrapper'));

    let mainElement = null;

    if (screenShareElement) {
        mainElement = screenShareElement;
    } else if (scwin.pinnedProducerId) {
        mainElement = scwin.remoteElements.get(scwin.pinnedProducerId);
    } else if (allElements.length > 0) {
        mainElement = allElements.find(el => !el.classList.contains('screen-share-wrapper')) || null;
    }

    // 기존 자식 노드를 모두 제거하여 깨끗하게 시작
    while (mainStage.firstChild) {
        mainStage.removeChild(mainStage.firstChild);
    }
    while (sidebar.firstChild) {
        sidebar.removeChild(sidebar.firstChild);
    }

    // 화면 공유 요소가 있다면 항상 메인 스테이지에 배치
    if (screenShareElement) {
        mainStage.appendChild(screenShareElement);
        allElements.forEach(el => {
            if (el !== screenShareElement) {
                sidebar.appendChild(el);
            }
        });
    } else if (mainElement) { // 화면 공유가 없고, 메인으로 지정된 요소가 있다면
        mainStage.appendChild(mainElement);
        allElements.forEach(el => {
            if (el !== mainElement) {
                sidebar.appendChild(el);
            }
        });
    } else { // 메인으로 지정된 요소가 없다면 모든 요소를 사이드바에 배치
        allElements.forEach(el => {
            sidebar.appendChild(el);
        });
    }
}
